<?php
declare(strict_types=1);
final class CommercialService {
 public function __construct(private PDO $db){}
 private function event(string $oid,string $uid,string $type,string $text,array $meta=[]):void{$this->db->prepare('INSERT INTO interactions(id,opportunity_id,user_id,type,description,metadata) VALUES(?,?,?,?,?,?)')->execute([uid(),$oid,$uid,$type,$text,$meta?json_encode($meta):null]);}
 private function opp(string $id,array $u):array{$q=$this->db->prepare('SELECT * FROM opportunities WHERE id=?');$q->execute([$id]);$o=$q->fetch();if(!$o)throw new RuntimeException('Oportunidade não encontrada.');if($u['role']==='broker'&&$o['broker_id']!==$u['id'])throw new AuthorizationException('Oportunidade pertence a outro corretor.');return $o;}
 public function interaction(string $id,array $d,array $u):void{$o=$this->opp($id,$u);if(!in_array($u['role'],['broker','manager','admin'],true))throw new AuthorizationException('Perfil sem permissão comercial.');validate_required($d,['type','description']);if(!in_array($d['type'],['call','message','meeting','note'],true))throw new InvalidArgumentException('Tipo inválido.');$this->event($id,$u['id'],$d['type'],$d['description']);$this->db->prepare('UPDATE opportunities SET last_contact_at=CURRENT_TIMESTAMP,next_contact_at=? WHERE id=?')->execute([!empty($d['next_contact_at'])?$d['next_contact_at']:null,$id]);if(!empty($d['next_contact_at']))$this->db->prepare('INSERT INTO tasks(id,opportunity_id,assigned_to,title,due_at) VALUES(?,?,?,?,?)')->execute([uid(),$id,$o['broker_id']?:$u['id'],'Follow-up comercial',$d['next_contact_at']]);}
 public function present(string $id,string $property,array $u,?string $notes):void{$this->opp($id,$u);$q=$this->db->prepare("SELECT title FROM properties WHERE id=? AND status IN ('available','reserved') AND listing_status='approved'");$q->execute([$property]);$title=$q->fetchColumn();if(!$title)throw new InvalidArgumentException('Imóvel indisponível ou inexistente.');$sql=$this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?'INSERT INTO opportunity_properties VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE notes=VALUES(notes),presented_at=CURRENT_TIMESTAMP':'INSERT INTO opportunity_properties VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(opportunity_id,property_id) DO UPDATE SET notes=excluded.notes,presented_at=CURRENT_TIMESTAMP';$this->db->prepare($sql)->execute([$id,$property,$u['id'],$notes]);$this->event($id,$u['id'],'property_presented','Imóvel apresentado: '.$title);}
 public function visit(string $oid,array $d,array $u):array{$o=$this->opp($oid,$u);validate_required($d,['property_id','scheduled_at','location']);$broker=$o['broker_id']?:$u['id'];$time=strtotime($d['scheduled_at']);$q=$this->db->prepare("SELECT COUNT(*) FROM visits v JOIN visit_statuses s ON s.`key`=v.status WHERE v.broker_id=? AND s.blocks_schedule=1 AND v.scheduled_at BETWEEN ? AND ?");$q->execute([$broker,date('Y-m-d H:i:s',$time-3600),date('Y-m-d H:i:s',$time+3600)]);if($q->fetchColumn())throw new DomainException('Conflito de horário com outra visita.');$id=uid();$this->db->prepare('INSERT INTO visits(id,opportunity_id,property_id,broker_id,scheduled_at,location,notes) VALUES(?,?,?,?,?,?,?)')->execute([$id,$oid,$d['property_id'],$broker,$d['scheduled_at'],$d['location'],$d['notes']??null]);$this->db->prepare("UPDATE opportunities SET stage='visit' WHERE id=?")->execute([$oid]);$this->event($oid,$u['id'],'visit_created','Visita agendada',['visit_id'=>$id]);return $this->visitGet($id);}
 public function visitUpdate(string $id,array $d,array $u):array{$v=$this->visitGet($id);$this->opp($v['opportunity_id'],$u);$status=$d['status']??'';$q=$this->db->prepare('SELECT * FROM visit_statuses WHERE `key`=?');$q->execute([$status]);$statusRow=$q->fetch();if(!$statusRow)throw new InvalidArgumentException('Status inválido.');if($statusRow['requires_reason']&&!trim((string)($d['cancellation_reason']??'')))throw new InvalidArgumentException('Motivo é obrigatório para este status.');$this->db->prepare('UPDATE visits SET status=?,cancellation_reason=?,result=?,feedback=? WHERE id=?')->execute([$status,$d['cancellation_reason']??null,$d['result']??null,$d['feedback']??null,$id]);$this->event($v['opportunity_id'],$u['id'],'visit_updated','Visita: '.$statusRow['label'],['visit_id'=>$id]);return $this->visitGet($id);}
 private function visitGet(string $id):array{$q=$this->db->prepare('SELECT * FROM visits WHERE id=?');$q->execute([$id]);$v=$q->fetch();if(!$v)throw new RuntimeException('Visita não encontrada.');return $v;}
 public function proposal(string $oid,array $d,array $u):array{$o=$this->opp($oid,$u);validate_required($d,['property_id','proposal_type','amount','proposal_date']);if((float)$d['amount']<=0)throw new InvalidArgumentException('Valor deve ser positivo.');$q=$this->db->prepare('SELECT purpose FROM properties WHERE id=?');$q->execute([$d['property_id']]);$purpose=$q->fetchColumn();if(!$purpose||!in_array($purpose,[$d['proposal_type'],'both'],true)||$o['interest_type']!==$d['proposal_type'])throw new InvalidArgumentException('Finalidades incompatíveis.');$id=uid();$status=$d['status']??'draft';$this->db->prepare('INSERT INTO proposals(id,opportunity_id,property_id,created_by,proposal_type,amount,commercial_terms,proposal_date,valid_until,status) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$id,$oid,$d['property_id'],$u['id'],$d['proposal_type'],$d['amount'],$d['commercial_terms']??null,$d['proposal_date'],!empty($d['valid_until'])?$d['valid_until']:null,$status]);$this->proposalEvent($id,$u['id'],'created',[],array_merge($d,['id'=>$id]));$this->db->prepare("UPDATE opportunities SET stage='proposal' WHERE id=?")->execute([$oid]);$this->event($oid,$u['id'],'proposal_created','Proposta criada');return $this->proposalGet($id);}
 public function proposalUpdate(string $id,array $d,array $u):array{$old=$this->proposalGet($id);$this->opp($old['opportunity_id'],$u);$flow=['draft'=>['sent','cancelled'],'sent'=>['under_review','accepted','rejected','cancelled'],'under_review'=>['accepted','rejected','cancelled'],'accepted'=>[],'rejected'=>[],'cancelled'=>[]];$status=$d['status']??$old['status'];if($status!==$old['status']&&!in_array($status,$flow[$old['status']],true))throw new DomainException('Transição de proposta não permitida.');$amount=$d['amount']??$old['amount'];if((float)$amount<=0)throw new InvalidArgumentException('Valor deve ser positivo.');$this->db->prepare('UPDATE proposals SET amount=?,commercial_terms=?,status=?,valid_until=? WHERE id=?')->execute([$amount,$d['commercial_terms']??$old['commercial_terms'],$status,$d['valid_until']??$old['valid_until'],$id]);$new=$this->proposalGet($id);$this->proposalEvent($id,$u['id'],'updated',$old,$new);if($status==='under_review')$this->db->prepare("UPDATE opportunities SET stage='negotiation' WHERE id=?")->execute([$old['opportunity_id']]);$this->event($old['opportunity_id'],$u['id'],'proposal_updated','Proposta: '.$old['status'].' → '.$status);return $new;}
 private function proposalGet(string $id):array{$q=$this->db->prepare('SELECT * FROM proposals WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)throw new RuntimeException('Proposta não encontrada.');return $p;}
 private function proposalEvent(string $id,string $uid,string $type,array $old,array $new):void{$this->db->prepare('INSERT INTO proposal_events(id,proposal_id,user_id,event_type,previous_data,new_data) VALUES(?,?,?,?,?,?)')->execute([uid(),$id,$uid,$type,$old?json_encode($old):null,json_encode($new)]);}
 public function negotiate(string $oid,array $d,array $u):void{$this->opp($oid,$u);validate_required($d,['notes']);if(isset($d['amount'])&&(float)$d['amount']<=0)throw new InvalidArgumentException('Contraproposta deve ser positiva.');$this->db->prepare('INSERT INTO negotiations(id,opportunity_id,proposal_id,user_id,amount,notes) VALUES(?,?,?,?,?,?)')->execute([uid(),$oid,$d['proposal_id']??null,$u['id'],$d['amount']??null,$d['notes']]);$this->db->prepare("UPDATE opportunities SET stage='negotiation' WHERE id=?")->execute([$oid]);$this->event($oid,$u['id'],'negotiation','Negociação registrada');}
 public function close(string $oid,array $d,array $u):void{$o=$this->opp($oid,$u);validate_required($d,['outcome','closing_date']);if($d['outcome']==='won'){validate_required($d,['property_id','business_type','final_amount']);if((float)$d['final_amount']<=0)throw new InvalidArgumentException('Valor final deve ser positivo.');}elseif($d['outcome']==='lost')validate_required($d,['loss_reason']);else throw new InvalidArgumentException('Resultado inválido.');$this->db->beginTransaction();try{$this->db->prepare('INSERT INTO closings(id,opportunity_id,property_id,responsible_id,outcome,business_type,final_amount,closing_date,loss_reason,notes,contract_reference,contract_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([uid(),$oid,$d['property_id']??null,$o['broker_id']?:$u['id'],$d['outcome'],$d['business_type']??null,$d['final_amount']??null,$d['closing_date'],$d['loss_reason']??null,$d['notes']??null,$d['contract_reference']??null,$d['contract_status']??null]);$this->db->prepare('UPDATE opportunities SET stage=?,loss_reason=?,closed_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$d['outcome'],$d['loss_reason']??null,$oid]);if($d['outcome']==='won')$this->db->prepare('UPDATE properties SET status=? WHERE id=?')->execute([$d['business_type']==='purchase'?'sold':'rented',$d['property_id']]);$this->event($oid,$u['id'],'closed',$d['outcome']==='won'?'Oportunidade ganha':'Oportunidade perdida');$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw $e;}}
 public function reopen(string $oid,string $reason,array $u):void{if(!in_array($u['role'],['admin','manager'],true))throw new AuthorizationException('Somente gestor ou administrador pode reabrir.');if(!trim($reason))throw new InvalidArgumentException('Motivo obrigatório.');$o=$this->opp($oid,$u);if(!in_array($o['stage'],['won','lost'],true))throw new DomainException('Oportunidade não encerrada.');$this->db->prepare("UPDATE opportunities SET stage='negotiation',closed_at=NULL,reopened_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$oid]);$this->db->prepare('DELETE FROM closings WHERE opportunity_id=?')->execute([$oid]);$this->event($oid,$u['id'],'reopened','Reaberta: '.$reason);}
}
